const input = $json.body ?? $json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const isText = (v) => typeof v === 'string' && v.trim().length > 0;
const hasOwn = (v, key) => Object.prototype.hasOwnProperty.call(v, key);
const isNullableVersion = (v) => v === null || (Number.isInteger(v) && v >= 0);
const isStateRef = (v) => isObj(v) && isText(v.scope) && isText(v.request_id) && isText(v.owner_id) && /^[0-9a-f]{64}$/.test(v.input_hash) && isText(v.execution_id) && Number.isInteger(v.state_revision) && v.state_revision >= 0;
const isSource = (v) => isObj(v) && isText(v.doc) && isText(v.section) && typeof v.score === 'number' && Number.isFinite(v.score);
const isFact = (v) => isObj(v) && isText(v.key) && typeof v.value === 'string' && ['user','document','api'].includes(v.origin) && (!hasOwn(v,'reference') || typeof v.reference === 'string');
const isFacts = (v) => isObj(v) && typeof v.summary === 'string' && Array.isArray(v.reported) && v.reported.every(isFact) && Array.isArray(v.confirmed) && v.confirmed.every(isFact) && Array.isArray(v.attempted_actions) && v.attempted_actions.every((x) => typeof x === 'string') && Array.isArray(v.missing) && v.missing.every((x) => typeof x === 'string') && Array.isArray(v.uncertainties) && v.uncertainties.every((x) => typeof x === 'string') && Array.isArray(v.evidence_refs) && v.evidence_refs.every(isSource);
const effect = () => ({status:'none'});
const effects = () => ({created_or_reused:effect(),context_saved:effect(),closed:effect(),assigned:effect(),alert:effect()});
const respond = (body, http_status) => ({route:'respond',body,http_status});
if (!isObj(input) || !isText(input.request_id) || !['lookup','process'].includes(input.kind)) return [{json:respond({request_id:isObj(input)&&isText(input.request_id)?input.request_id:null,status:'error',record:null,masked:0,error_code:'invalid_tool_request'},400)}];
if (input.kind === 'lookup') {
  const valid = typeof input.enabled === 'boolean' && isText(input.actor_id) && (input.target_ticket_id === null || isText(input.target_ticket_id));
  if (!valid) return [{json:respond({request_id:input.request_id,status:'error',record:null,masked:0,error_code:'invalid_tool_request'},400)}];
  if (!input.enabled) return [{json:respond({request_id:input.request_id,status:'skipped',record:null,masked:0,error_code:null},200)}];
  if (input.target_ticket_id === null) return [{json:respond({request_id:input.request_id,status:'error',record:null,masked:0,error_code:'invalid_tool_request'},400)}];
  return [{json:{route:'lookup',request:{request_id:input.request_id,actor_id:input.actor_id,target_ticket_id:input.target_ticket_id}}}];
}
const valid = isStateRef(input.state_ref) && hasOwn(input,'expected_case_version') && isNullableVersion(input.expected_case_version) && isText(input.case_id) && isText(input.actor_id) && isText(input.first_request_id) && Number.isInteger(input.attempt) && input.attempt >= 1 && (input.ticket_id === null || isText(input.ticket_id)) && isText(input.title) && isText(input.category) && ['close','wait','handoff'].includes(input.action) && ['normal','high'].includes(input.priority) && hasOwn(input,'assignee_role') && (input.assignee_role === null || isText(input.assignee_role)) && isFacts(input.context) && typeof input.answer === 'string' && Array.isArray(input.sources) && input.sources.every(isSource) && hasOwn(input,'close_status') && (input.close_status === null || ['closed_guidance','closed_rejected'].includes(input.close_status)) && isText(input.transition_key);
if (!valid) return [{json:respond({request_id:input.request_id,ticket_id:input.ticket_id??null,case_version:null,state_saved:false,state_ref:null,recovery:{version:1,mode:'manual_required',action:'inspect_only',args:null,reference:null,reason:'티켓 요청 계약 오류'},effects:effects(),error_code:'invalid_tool_request'},400)}];
return [{json:{route:'prepare',op:'prepare',state_ref:input.state_ref,args:{current_step:'H05'},request:input}}];

const original = $('H02 요청 계약 검사').item.json.request;
const state = $json;
const effect = () => ({status:'none'});
const effects = () => ({created_or_reused:effect(),context_saved:effect(),closed:effect(),assigned:effect(),alert:effect()});
if (state.ok !== true || state.skipped === true || !state.state_ref) return [{json:{route:'respond',body:{request_id:original.request_id,ticket_id:original.ticket_id??null,case_version:null,state_saved:false,state_ref:null,recovery:{version:1,mode:'manual_required',action:'create',args:null,reference:null,reason:'Jira 실행 전 상태 저장 실패'},effects:effects(),error_code:'state_error'},http_status:200}}];
return [{json:{route:'fail',op:'fail',state_ref:state.state_ref,args:{status:'failed',current_step:'H05',error_code:'tickets_down'},request:original}}];

const original = $('H02 요청 계약 검사').item.json.request;
const result = $json;
const effect = () => ({status:'none'});
return [{json:{body:{request_id:original.request_id,ticket_id:original.ticket_id??null,case_version:null,state_saved:result.ok===true&&result.skipped!==true,state_ref:result.state_ref??null,recovery:{version:1,mode:'manual_required',action:'create',args:null,reference:null,reason:'Jira 어댑터 미연결로 외부 작업 차단'},effects:{created_or_reused:effect(),context_saved:effect(),closed:effect(),assigned:effect(),alert:effect()},error_code:'tickets_down'},http_status:200}}];

const req = $('H02 요청 계약 검사').item.json.request;
const raw = $json;
const statusCode = Number(raw.statusCode ?? 0);
const body = raw.body;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reply = (status, record, masked, error_code) => [{json:{route:'respond',http_status:200,body:{request_id:req.request_id,status,record,masked,error_code}}}];
// 403/404는 같은 denied로 합쳐 타인 건의 존재 여부를 알리지 않는다.
if (statusCode === 403 || statusCode === 404) return reply('denied', null, 0, null);
if (statusCode !== 200 || !isObj(body) || typeof body.status !== 'string' || body.ticket_id !== req.target_ticket_id) return reply('error', null, 0, 'lookup_error');
// 서버가 본인 건만 돌려주더라도 owner를 한 번 더 대조한다. 어긋나면 내용 없이 denied.
if (body.owner_id !== req.actor_id) return reply('denied', null, 0, null);
const contact = isObj(body.contact) ? body.contact : {};
const record = { ticket_id: body.ticket_id, owner_id: body.owner_id, status: body.status, observed_at: new Date().toISOString() };
let masked = 0;
if (typeof contact.phone === 'string') { record.masked_phone = contact.phone; masked += 1; }
if (typeof contact.email === 'string') { record.masked_email = contact.email; masked += 1; }
return reply('ok', record, masked, null);
